#pragma once

#include <cstdint>

namespace trillion {

/// Newton iterations of `waveRest`: two leave 1.3 cm at the steepest crests, three 0.3 mm.
constexpr int HEIGHT_ITERATIONS = 3;

/// One wave as `jolt_wave_buffer` takes it (`waves.ts` WAVE_FIELDS).
struct Wave {
  double dirX, dirZ, k, amplitude, lateral, phase;
};
/// Doubles of one wave.
constexpr uint32_t WAVE_DOUBLES = 6;

/// `sin` and `cos` of `x` (`waterPlanes.cpp`).
void sinCos(double x, double &s, double &c);

/// The rest point `[x, ·, z]` the waves carry to the world position `(x, z)`, into `out`; the
/// physics module runs its C++ print (`scripts/generate-shared-rules.ts`).
inline void waveRest(const Wave *waves, uint32_t count, double x, double z, double &restX,
                     double &restZ) {
  double px = x, pz = z;
  for (int n = 0; n < HEIGHT_ITERATIONS; n++) {
    double fx = px - x, fz = pz - z, sxx = 0, sxz = 0, szz = 0;
    for (uint32_t i = 0; i < count; i++) {
      const double dx = waves[i].dirX, dz = waves[i].dirZ, k = waves[i].k, lateral = waves[i].lateral;
      const double f = k * (dx * px + dz * pz) - waves[i].phase;
      double sinF, cosF;
      sinCos(f, sinF, cosF);
      const double c = cosF, s = sinF;
      const double qs = k * lateral * s;
      fx += lateral * dx * c;
      fz += lateral * dz * c;
      sxx += qs * dx * dx;
      sxz += qs * dx * dz;
      szz += qs * dz * dz;
    }
    const double a = 1 - sxx, d = 1 - szz, det = a * d - sxz * sxz;
    if (!(det > 1e-6)) {
      px -= fx;
      pz -= fz;
      continue;
    }
    px -= (d * fx + sxz * fz) / det;
    pz -= (sxz * fx + a * fz) / det;
  }
  restX = px;
  restZ = pz;
}

}  // namespace trillion
